use std::sync::atomic::{AtomicBool, Ordering};

static DROPPED: AtomicBool = AtomicBool::new(false);

struct Handle;
impl Drop for Handle {
    fn drop(&mut self) {
        DROPPED.store(true, Ordering::SeqCst);
    }
}

fn check_drop(h: Handle) -> bool {
    ⟦drop_op⟧;
    DROPPED.load(Ordering::SeqCst)
}
